-- 195: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_195_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_195_guard;
INSERT INTO _migration_195_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_009' AND NOT (q.topic_id IS 'topic_was_basketry_b004_2' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which sequence best controls chemical colouring of prepared bamboo strips?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Place partly dry and fully damp sized strips together in a measured bath, then rinse and dry them at one time","B. Prepare a measured bath, add strips in several timed batches, remove them together, then rinse and dry","C. Clean and size the strips, prepare a measured bath, immerse for a controlled time, rinse or neutralise as directed, then dry","D. Clean broad strips, colour them before final sizing, shave them to width, then dry without a final rinse"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Controlled chemical colouring begins with uniformly prepared bamboo and a measured compatible bath, followed by equal exposure, the specified rinse or neutralisation, and thorough drying for repeatable colour and safer handling. Therefore the correct answer is C: Clean and size the strips, prepare a measured bath, immerse for a controlled time, rinse or neutralise as directed, then dry.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_009' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_195_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_010' AND NOT (q.topic_id IS 'topic_was_basketry_b004_2' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should prepared basketry materials be stored before use?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Raised in a dry ventilated place and protected from pests","B. Stack dry strips directly on a concrete floor under an open cover because the room is ventilated","C. Tie all graded strips into dense bundles and inspect them only when they are issued for weaving","D. Keep freshly conditioned strips sealed in plastic sacks in a warm room for several days to preserve flexibility"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Dry ventilated storage limits mould, staining and pest activity while preserving material condition; wet sealed bundles create a favourable environment for biological deterioration. Therefore the correct answer is A: Raised in a dry ventilated place and protected from pests.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_010' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_195_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_011' AND NOT (q.topic_id IS 'topic_was_basketry_b004_3' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the safest method for trimming a tough cane strip with a knife?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Hold the strip unsupported so it can move away from a heavy stroke","B. Use a blunt knife with greater force because it is less likely to cut skin","C. Brace the strip against the palm and cut toward the supporting hand","D. Secure the material and cut away from the body with a controlled stroke"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Securing the work and directing a sharp blade away from the body improves control and keeps hands outside the cutting path, reducing slips caused by unstable material or excessive force. Therefore the correct answer is D: Secure the material and cut away from the body with a controlled stroke.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_011' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_195_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_012' AND NOT (q.topic_id IS 'topic_was_basketry_b004_3' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which description identifies a Josephine knot in decorative basketry or cord work?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A folded cord passes around a support to form a lark’s-head attachment","B. Two interlaced bights form a flat symmetrical decorative knot","C. A working cord makes successive half hitches along one holding cord","D. Two cord ends cross once and tighten into a compact overhand stopper"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The Josephine knot is recognised by its balanced interlaced loops and flat decorative form; the alternatives describe other useful knots but not its distinctive structure. Therefore the correct answer is B: Two interlaced bights form a flat symmetrical decorative knot.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_012' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_009', 'topic_was_basketry_b004_2', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which sequence best controls chemical colouring of prepared bamboo strips?', 'multiple_choice', NULL, '["A. Place partly dry and fully damp sized strips together in a measured bath, then rinse and dry them at one time","B. Prepare a measured bath, add strips in several timed batches, remove them together, then rinse and dry","C. Clean and size the strips, prepare a measured bath, immerse for a controlled time, rinse or neutralise as directed, then dry","D. Clean broad strips, colour them before final sizing, shave them to width, then dry without a final rinse"]', 'C', 'Controlled chemical colouring begins with uniformly prepared bamboo and a measured compatible bath, followed by equal exposure, the specified rinse or neutralisation, and thorough drying for repeatable colour and safer handling. Therefore the correct answer is C: Clean and size the strips, prepare a measured bath, immerse for a controlled time, rinse or neutralise as directed, then dry.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_010', 'topic_was_basketry_b004_2', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'How should prepared basketry materials be stored before use?', 'multiple_choice', NULL, '["A. Raised in a dry ventilated place and protected from pests","B. Stack dry strips directly on a concrete floor under an open cover because the room is ventilated","C. Tie all graded strips into dense bundles and inspect them only when they are issued for weaving","D. Keep freshly conditioned strips sealed in plastic sacks in a warm room for several days to preserve flexibility"]', 'A', 'Dry ventilated storage limits mould, staining and pest activity while preserving material condition; wet sealed bundles create a favourable environment for biological deterioration. Therefore the correct answer is A: Raised in a dry ventilated place and protected from pests.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_2', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_011', 'topic_was_basketry_b004_3', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What is the safest method for trimming a tough cane strip with a knife?', 'multiple_choice', NULL, '["A. Hold the strip unsupported so it can move away from a heavy stroke","B. Use a blunt knife with greater force because it is less likely to cut skin","C. Brace the strip against the palm and cut toward the supporting hand","D. Secure the material and cut away from the body with a controlled stroke"]', 'D', 'Securing the work and directing a sharp blade away from the body improves control and keeps hands outside the cutting path, reducing slips caused by unstable material or excessive force. Therefore the correct answer is D: Secure the material and cut away from the body with a controlled stroke.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_012', 'topic_was_basketry_b004_3', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which description identifies a Josephine knot in decorative basketry or cord work?', 'multiple_choice', NULL, '["A. A folded cord passes around a support to form a lark’s-head attachment","B. Two interlaced bights form a flat symmetrical decorative knot","C. A working cord makes successive half hitches along one holding cord","D. Two cord ends cross once and tighten into a compact overhand stopper"]', 'B', 'The Josephine knot is recognised by its balanced interlaced loops and flat decorative form; the alternatives describe other useful knots but not its distinctive structure. Therefore the correct answer is B: Two interlaced bights form a flat symmetrical decorative knot.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_3', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_basketry_b004_009', 'q_was_basketry_b004_010', 'q_was_basketry_b004_011', 'q_was_basketry_b004_012');
